off num_reaches = max(2, int(time_concentration / duration_step)) for i in range(num_reaches): # Storage routing calculation storage_coeff = time_concentration / num_reaches routed = routed * (1 - np.exp(-duration_step / storage_coeff)) return routed def baseflow_separation(total_runoff, antecedent_moisture=0.5): &quot;&quot;&quot; Separate baseflow from total runoff using exponential decay method. Compute-heavy operation that iterates multiple recession curves. Parameters ---------- total_runoff : float Total runoff depth (mm) antecedent_moisture : float Antecedent moisture condition (0-1) Returns ------- tuple (direct_runoff, baseflow, recession_index) &quot;&quot;&quot; # Simulate multiple recession curve iterations recession_constant = 0.95 - (antecedent_moisture * 0.3) direct_runoff = total_runoff * (1 - antecedent_moisture) baseflow = total_runoff * antecedent_moisture # Iterative recession calculation recession_index = 0.0 for day in range(1, 31): # 30-day recession recession_index += baseflow * (recession_constant ** day) return direct_runoff, baseflow, recession_index def calculate_peak_discharge(runoff, contributing_area_sqkm, time_concentration): &quot;&quot;&quot; Calculate peak discharge using rational method with intensity. Uses nested computations to increase computational load. Parameters ---------- runoff : float Direct runoff depth (mm) contributing_area_sqkm : float Contributing watershed area (km²) time_concentration : float Time of concentration (minutes) Returns ------- float Peak discharge (m³/s) &quot;&quot;&quot; # Rainfall intensity approximation intensity = 100 / (time_concentration + 10) ** 0.7 # Convert units and calculate peak area_m2 = contributing_area_sqkm * 1e6 runoff_m3 = (runoff / 1000) * area_m2 # Time distribution computation peak_factor = 0.0 for t in np.linspace(0, time_concentration, 50): peak_factor += np.sin(np.pi * t / time_concentration) * intensity / 50 return (runoff_m3 * peak_factor) / (time_concentration * 60) def mai