** 0.7 area_m2 = contributing_area_sqkm * 1e6 runoff_m3 = (runoff / 1000.0) * area_m2 peak_factor = 0.0 for t in np.linspace(0.0, time_concentration, 50): peak_factor += np.sin(np.pi * t / time_concentration) * intensity / 50.0 return (runoff_m3 * peak_factor) / (time_concentration * 60.0) def compute_partition_metrics(df): &quot;&quot;&quot;Compute the full hydrology workflow on a dataframe partition.&quot;&quot;&quot; df['runoff_scs'] = df.apply( lambda row: scs_runoff(row['precipitation_mm'], row['curve_number']), axis=1 ) df['routed_runoff'] = df.apply( lambda row: clark_routing(row['runoff_scs'], row['time_concentration']), axis=1 ) baseflow_results = df.apply( lambda row: baseflow_separation(row['routed_runoff'], row['antecedent_moisture']), axis=1, result_type='expand' ) df['direct_runoff'] = baseflow_results[0] df['baseflow'] = baseflow_results[1] df['recession_index'] = baseflow_results[2] df['peak_discharge'] = df.apply( lambda row: calculate_peak_discharge( row['direct_runoff'], row['contributing_area'], row['time_concentration'] ), axis=1 ) return df def main(): comm = MPI.COMM_WORLD rank = comm.Get_rank() size = comm.Get_size() if rank == 0: print(&quot;=&quot; * 60) print(&quot;Hydrology MPI Example - Parallel SCS Runoff Workflow&quot;) print(f&quot;Running on {size} processes&quot;) print(&quot;=&quot; * 60) input_file = 'hydrology_data_50k.csv' print(f&quot;
